const item = $input.item.json;
const rawUrl = (item.link && item.link[0]) || (item.guid && item.guid[0]) || '';
const url = rawUrl.split('?')[0];
const id = Buffer.from(url).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);
const description = ((item.description && item.description[0]) || '')
  .replace(/<[^>]+>/g, '').slice(0, 1500);
return {
  id,
  title: (item.title && item.title[0]) || '',
  company: (item['indeed:company'] && item['indeed:company'][0]) || '',
  location: (item['indeed:formattedLocation'] && item['indeed:formattedLocation'][0]) || (item['indeed:city'] && item['indeed:city'][0]) || '',
  description,
  url,
  posted_date: (item.pubDate && item.pubDate[0]) || '',
  source: 'Indeed'
};

const job = $input.item.json;
const refnr = job.referenznummer || job.refnr || '';
const url = job.externeURL || job.externeUrl || ('https://www.arbeitsagentur.de/jobsuche/jobdetail/' + refnr);
const id = Buffer.from(refnr || url).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);
const locations = job.stellenlokationen || [];
const address = (locations[0] && locations[0].adresse) || job.arbeitsort || {};
const location = [address.ort, address.region].filter(Boolean).join(', ');
const salary = job.gehaltsspanneVon || job.gehaltsspanneBis ? `Jahresgehalt ${job.gehaltsspanneVon || '?'} bis ${job.gehaltsspanneBis || '?'} EUR` : '';
const description = [job.hauptberuf || '', salary, job.homeofficemoeglich ? 'Homeoffice moeglich; Umfang unklar' : ''].filter(Boolean).join(' | ');
return {
  id,
  title: job.stellenangebotsTitel || job.titel || '',
  company: job.firma || job.arbeitgeber || '',
  location,
  description: description.slice(0, 1500),
  url,
  posted_date: job.datumErsteVeroeffentlichung || (job.veroeffentlichungszeitraum && job.veroeffentlichungszeitraum.von) || '',
  salary_min: job.gehaltsspanneVon || null,
  salary_max: job.gehaltsspanneBis || null,
  source: 'Arbeitsagentur'
};

const result = $input.item.json;
const html = typeof result === 'string'
  ? result
  : (result.body || result.data || result.response || result.html || '');

function clean(value) {
  return String(value || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/&#x27;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function pick(part, cls) {
  const re = new RegExp('<[^>]*class="[^"]*' + cls + '[^"]*"[^>]*>([\\s\\S]*?)<\\/[^>]+>', 'i');
  const match = part.match(re);
  return clean(match && match[1]);
}

function attr(part, name) {
  const re = new RegExp(name + '="([^"]+)"', 'i');
  const match = part.match(re);
  return match ? clean(match[1]) : '';
}

const jobs = [];
for (const part of html.split(/<li\b/i).slice(1)) {
  const title = pick(part, 'base-search-card__title');
  const company = pick(part, 'base-search-card__subtitle');
  if (!title || !company) continue;
  const location = pick(part, 'job-search-card__location') || 'Deutschland';
  const urlMatch = part.match(/<a[^>]+href=["']([^"']+)["'][^>]*class=["'][^"']*base-card__full-link/i)
    || part.match(/<a[^>]+class=["'][^"']*base-card__full-link[^"']*["'][^>]+href=["']([^"']+)["']/i)
    || part.match(/<a[^>]+href=["']([^"']+)["']/i);
  const url = clean(urlMatch && urlMatch[1]).split('?')[0];
  const posted = attr(part, 'datetime');
  jobs.push({
    title,
    company,
    location,
    url,
    postedAt: posted,
    description: 'LinkedIn search result: ' + company,
    source: 'LinkedIn'
  });
}

return { jobs };

const job = $input.item.json;
const rawUrl = job.jobUrl || job.url || job.applyUrl || job.link || '';
const url = rawUrl.split('?')[0];
const id = Buffer.from(url || job.id || '').toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 32);
const company = (job.company && (job.company.name || job.company)) || job.companyName || '';
return {
  id,
  title: job.title || job.jobTitle || '',
  company,
  location: job.location || job.formattedLocation || job.city || '',
  description: (job.description || job.shortDescription || job.snippet || '').slice(0, 1500),
  url,
  posted_date: job.listedAt || job.postedAt || job.datePosted || '',
  source: 'LinkedIn'
};

const PROFILE_VERSION = '2026-08-03-master-v1';
const staticData = $getWorkflowStaticData('global');
if (staticData.profileVersion !== PROFILE_VERSION) {
  staticData.seenIds = {};
  staticData.profileVersion = PROFILE_VERSION;
}
if (!staticData.seenIds) staticData.seenIds = {};
const all = $input.all();
const inRun = new Set();
const result = [];
for (const item of all) {
  const { id, source } = item.json;
  if (!id || !source) continue;
  if (staticData.seenIds[id] || inRun.has(id)) continue;
  inRun.add(id);
  result.push(item);
}
for (const id of inRun) {
  staticData.seenIds[id] = new Date().toISOString().slice(0, 10);
}
return result;

const POSITIVE = {'gkv':20,'krankenkasse':18,'sozialversicherung':18,'payer':14,'payor':14,'public sector':16,'healthcare':14,'health it':15,'digital health':14,'strategic account manager':18,'senior account manager':18,'key account manager':16,'senior sales manager':18,'enterprise account executive':20,'senior account executive':18,'named account executive':18,'business development manager':14,'client partner':15,'partner manager':12,'market access':15,'vertragsmanager':14,'vertragsverhandler':14,'ausschreibung':15,'vergabe':14,'tender':12,'enterprise':10,'cloud':10,'managed services':12,'cybersecurity':12,'security':8,'compliance':10,'data & ai':12,'saas':10,'plattform':8,'remote':5,'hamburg':5};
const NEGATIVE = {'zeitarbeit':-40,'leiharbeit':-40,'sachbearbeiter':-100,'kundenberater':-80,'werkstudent':-100,'praktikum':-100,'trainee':-100,'junior':-100,'pflege':-100,'arzt':-80,'produktion':-60,'logistik':-40,'automotive':-100};
const EXCLUDED = ['adesso','hbsn consulting','init','exxeta','hmm','hcvision','puntus','bitmarck','arvato systems','d velop','ferchau','faktor d','x tention','iqvia','davaso','comline','act digital','cloudflight','kwsoft','nice','cognigy','smart2success','aquinet','ipsways','gkv informatik','convista','agorum','aok'];
const PRIORITY_TECH = ['deepl','sap','genesys','veeam','salesforce','softwareone','amazon web services','camunda','public cloud group','appzen','gartner','snaplogic','ashby','360learning','conceptboard'];
const item = $input.item.json;
if (!item.title) return null;
const norm = value => String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, ' und ').replace(/[^a-z0-9]+/g, ' ').trim();
const company = ' ' + norm(item.company) + ' ';
const companyHas = value => company.includes(' ' + norm(value) + ' ');
if (companyHas('acture')) return {...item, keyword_score:0, filter_reason:'already_applied'};
if (EXCLUDED.some(companyHas)) return {...item, keyword_score:0, filter_reason:'excluded_company'};
const title = norm(item.title);
const description = norm(item.description);
if (companyHas('atacama') && (title + ' ' + description).includes('oscare')) return {...item, keyword_score:0, filter_reason:'excluded_required_experience'};
const hardTitles = ['sachbearbeiter','kundenberater','kundenservice','servicecenter','call center','sozialversicherungsfachangestell','fallmanager','case manager','pflege','arzt','therapeut','buchhaltung','controller','recruiter','werkstudent','praktikant','trainee','junior'];
if (hardTitles.some(x => title.includes(x))) return {...item, keyword_score:0, filter_reason:'hard_exclude_title'};
const location = norm(item.location);
const local = ['hamburg','norderstedt','ahrensburg','pinneberg','wedel','reinbek','glinde','barsbuttel','schenefeld','quickborn','halstenbek','bonningstedt','neu wulmstorf','seevetal','buchholz','winsen','geesthacht','elmshorn','stade'].some(x => location.includes(x));
const foreign = ['united states','usa','united kingdom','london','england','ireland','france','paris','spain','madrid','italy','milan','netherlands','amsterdam','switzerland','zurich','austria','vienna','poland','warsaw','remote us','remote usa','europe','emea','worldwide','global remote'].some(x => location.includes(x)) || /(^| )us( |$)/.test(title + ' ' + location);
if (foreign) return {...item, keyword_score:0, filter_reason:'foreign_location'};
const remoteContext = location + ' ' + description;
const remote = ['remote','fully remote','100 homeoffice','work from anywhere'].some(x => remoteContext.includes(x));
const country = ['deutschland','germany','bundesweit','deutschlandweit','dach'].some(x => (title + ' ' + location + ' ' + description).includes(x));
if (location && !local && remote && !country) return {...item, keyword_score:0, filter_reason:'remote_country_unknown'};
if (location && !local && !(remote && country) && !['deutschland','germany','bundesweit','deutschlandweit'].includes(location)) return {...item, keyword_score:0, filter_reason:'outside_hamburg_or_remote'};
const query = norm(item.matched_query);
const text = [title, description, company, location, query].join(' ');
const has = words => words.some(x => text.includes(norm(x)));
const commercial = ['strategic account manager','senior account manager','key account manager','senior sales manager','sales director','enterprise account executive','senior account executive','named account executive','business development manager','client partner','partner manager','alliance manager','commercial lead','go to market','head of sales','head of business development','leiter vertrieb'].some(x => title.includes(x));
const transferTitle = ['strategic account manager','senior account manager','senior sales manager','sales director','enterprise account executive','senior account executive','named account executive','client partner','commercial lead','head of sales'].some(x => title.includes(x));
const alternative = ['market access','payer partnership','payor partnership','strategic partnership','vertragsmanager','vertragsreferent','vertragsverhandler','partnermanager'].some(x => title.includes(x));
const internalTitle = ['leiter digital','leiter it strategie','leiter it steuerung','leiter unternehmensentwicklung','leiter vergabemanagement','leiter einkauf','bereichsleiter digital','head of digital','head of it strategy','head of it governance','head of procurement','chief digital officer'].some(x => title.includes(x));
const gkv = has(['gkv','gesetzliche krankenversicherung','krankenkasse','bkk','ikk','sozialversicherung','payer','payor','kostentrager','bitmarck','iskv']);
const health = has(['healthcare','health care','health it','gesundheitswesen','ehealth','digital health','public healthcare','telematikinfrastruktur']);
const publicSector = has(['public sector','public services','offentlicher sektor','government','behorde','verwaltung','sozialversicherung']);
const tech = has(['software','saas','cloud','managed services','cybersecurity','security','compliance','kritis','nis2','data & ai','data ai','artificial intelligence','genai','plattform','platform','digital transformation','it system','infrastruktur']);
const enterprise = has(['enterprise','senior account','strategic account','named account','major account','large account','grosskunden','c level','buying committee','complex sales','large deal','sales director']);
const payerCommercial = has(['ausschreibung','vergabe','tender','vertrag','market access','payer','payor','kostentrager','versicherung','insurer']);
const priorityTech = PRIORITY_TECH.some(companyHas);
const gkvEmployer = has(['krankenkasse','bkk','ikk','dak','techniker krankenkasse','barmer','hkk','kaufmannische krankenkasse']);
const validTrack = (commercial && gkv)
  || (commercial && health)
  || (commercial && publicSector && (tech || priorityTech))
  || (transferTitle && enterprise && (tech || priorityTech))
  || (alternative && (gkv || health) && payerCommercial)
  || (internalTitle && gkvEmployer);
if (!validTrack) return {...item, keyword_score:0, filter_reason:'missing_search_track'};
let score = 0;
for (const [kw, pts] of Object.entries(POSITIVE)) { if (text.includes(norm(kw))) score += pts; }
for (const [kw, pen] of Object.entries(NEGATIVE)) { if (text.includes(norm(kw))) score += pen; }
if (priorityTech) score += 8;
return {...item, keyword_score:Math.max(0, Math.min(100, score)), profile_version:'2026-08-03-master-v1'};

